const CorporateHero = () => {
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedMode = localStorage.getItem('theme');
    return savedMode ? savedMode === 'dark' : false;
  });
  const logoColor = isDarkMode ? "#ffffff" : "#000000";
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const observer = new MutationObserver(() => {
      const theme = document.documentElement.getAttribute('theme');
      setIsDarkMode(theme === 'dark');
    });

    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['theme']
    });

    return () => observer.disconnect();
  }, []);

  const companyNames = [
    "Reliance Industries",
    "Endurance",
    "Dr. Reddy's",
    "Bosch",
    "Hindustan Petroleum",
    "Merck",
    "Narayana Healthcare",
    "Panasonic",
    "Cotiviti",
  ];

  useEffect(() => {
    setIsVisible(true);
  }, []);

  const cards = [
    {
      icon: <GlobalIcon />,
      title: "Global Enterprises",
      description: "Fortune 500 companies seeking strategic advantage and operational transformation",
      bg: "#512EAB",
    },
    {
      icon: <GrowthIcon />,
      title: "Growth Companies",
      description: "Scale-ups and mid-market leaders navigating rapid expansion and market disruption",
      bg: "linear-gradient(180deg, #0D004D 0%, #1E00B3 100%)",
    },
    {
      icon: <EquityIcon />,
      title: "Private Equity",
      description: "Investment firms optimizing portfolio company performance and value creation",
      bg: "linear-gradient(180deg, #0D004D 0%, #1E00B3 100%)",
    },
  ];


  return (
    <section
      style={{
        padding: "clamp(40px, 10vw, 100px) clamp(12px, 5vw, 20px)",
        background: isDarkMode ? "#090B0E" : "#F9FAFB",
        textAlign: "center",
      }}
    >
      <div style={{ maxWidth: "1200px", margin: "0 auto" }}>

        {/* Heading */}
        <h1
          style={{
            maxWidth: "800px",
            margin: "0 auto 24px",
            fontFamily: "Inter, sans-serif",
            fontStyle: "normal",
            fontWeight: 600,
            fontSize: "clamp(40px, 5vw, 70px)",
            lineHeight: "1",
            letterSpacing: "-0.05em",
            textAlign: "center",
            background:
              "linear-gradient(90deg, #1447E6 0%, #9C2DA9 100%)",
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
            backgroundClip: "text",
            opacity: isVisible ? 1 : 0,
            transform: isVisible ? "translateY(0)" : "translateY(30px)",
            transition: "all 0.8s cubic-bezier(0.4, 0, 0.2, 1)",
          }}
        >
          Strategy That Drives Lasting Impact
        </h1>

        {/* Description */}
        <p
          style={{
            maxWidth: "560px",
            margin: "0 auto 40px",
            fontFamily: "Inter, sans-serif",
            fontWeight: 400,
            fontSize: "clamp(14px, 4vw, 18px)",
            lineHeight: "1.5",
            letterSpacing: "-0.8px",
            textAlign: "center",
            color: "#5E6774",
            opacity: isVisible ? 1 : 0,
            transform: isVisible ? "translateY(0)" : "translateY(30px)",
            transition: "all 0.8s cubic-bezier(0.4, 0, 0.2, 1) 0.2s",
          }}
        >
          Partner with premier management consultants who transform complex
          challenges into sustainable competitive advantage. We deliver results
          that matter.
        </p>

        
        <button style={{
          padding: "14px 28px",
          borderRadius: "50px",
          fontSize: "16px",
          fontWeight: 500,
          cursor: "pointer",
          border: "none",
          transition: "all 0.3s ease",
          background:"linear-gradient(90deg, #1447E6 0%, #9C2DA9 100%)",
          color: "#fff",
          }}
          onClick={() => {window.open(FlagshipPrograms,'_blank')}}
          >
            Learn More ↓
        </button>
        

      

        {/* Cards Section */}
        <div
          style={{
            display: "flex",
            gap: "clamp(12px, 3vw, 24px)",
            marginTop: "clamp(40px, 8vw, 60px)",
            justifyContent: "center",
            flexWrap: "wrap",
          }}
        >
          {cards.map((card, i) => (
            <div
              key={i}
              style={{
                flex: "1 1 0",
                minWidth: "min(100%, 280px)",
                maxWidth: "403px",
                background: card.bg,
                borderRadius: "clamp(16px, 4vw, 24px)",
                padding: "clamp(20px, 5vw, 32px)",
                display: "flex",
                flexDirection: "column",
                alignItems: "flex-start",
                gap: "10.8px",
                textAlign: "left",
                transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
                cursor: "pointer",
                position: "relative",
                overflow: "hidden",
                boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
                opacity: isVisible ? 1 : 0,
                transform: isVisible ? "translateY(0)" : "translateY(40px)",
                transitionDelay: `${0.6 + i * 0.1}s`,
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = "translateY(-8px) scale(1.02)";
                e.currentTarget.style.boxShadow = "0 20px 40px rgba(81, 46, 171, 0.4)";
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = "translateY(0) scale(1)";
                e.currentTarget.style.boxShadow = "0 4px 6px rgba(0, 0, 0, 0.1)";
              }}
            >
              <div
                style={{
                  width: "40px",
                  height: "40px",
                  transition: "transform 0.3s ease",
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = "rotate(10deg) scale(1.1)";
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = "rotate(0deg) scale(1)";
                }}
              >
                {card.icon}
              </div>
              <h3
                style={{
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  fontWeight: 600,
                  fontSize: "clamp(18px, 5vw, 24px)",
                  lineHeight: "1.4",
                  color: "#D6D5FB",
                  margin: 0,
                  transition: "color 0.3s ease",
                }}
              >
                {card.title}
              </h3>
              <p
                style={{
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  fontWeight: 400,
                  fontSize: "clamp(14px, 3.5vw, 16px)",
                  lineHeight: "1.6",
                  color: "#F9F9FC",
                  margin: 0,
                }}
              >
                {card.description}
              </p>
            </div>
          ))}
        </div>

        {/* Company Names Carousel */}
        <div
          style={{
            marginTop: "clamp(40px, 10vw, 80px)",
            paddingTop: "clamp(20px, 5vw, 40px)",
            paddingBottom: "clamp(20px, 5vw, 40px)",
            marginLeft: "calc(-50vw + 50%)",
            marginRight: "calc(-50vw + 50%)",
            width: "100vw",
            overflow: "hidden",
          }}
        >
          <p
            style={{
              fontFamily: "'Plus Jakarta Sans', sans-serif",
              fontSize: "clamp(12px, 2.5vw, 14px)",
              fontWeight: 600,
              textTransform: "uppercase",
              letterSpacing: "1.5px",
              color: isDarkMode ? "rgba(255,255,255,0.5)" : "rgba(0,0,0,0.5)",
              marginBottom: "clamp(20px, 4vw, 32px)",
              textAlign: "center",
            }}
          >
            Our Trusted Partners
          </p>
          <Marquee gradient={false} speed={90} pauseOnHover={true}>
            {[...companyNames, ...companyNames, ...companyNames].map((name, index) => (
              <div
                key={index}
                style={{
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  fontSize: "clamp(16px, 4vw, 20px)",
                  fontWeight: 600,
                  color: isDarkMode ? "rgba(255,255,255,0.7)" : "rgba(0,0,0,0.7)",
                  padding: "0 clamp(32px, 8vw, 64px)",
                  whiteSpace: "nowrap",
                  transition: "all 0.3s ease",
                  cursor: "default",
                  opacity: 0.8,
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.opacity = "1";
                  e.currentTarget.style.transform = "scale(1.05)";
                  e.currentTarget.style.color = isDarkMode ? "#FFFFFF" : "#000000";
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.opacity = "0.8";
                  e.currentTarget.style.transform = "scale(1)";
                  e.currentTarget.style.color = isDarkMode ? "rgba(255,255,255,0.7)" : "rgba(0,0,0,0.7)";
                }}
              >
                {name}
              </div>
            ))}
          </Marquee>
        </div>

      </div>

    </section>
  );
};

export default CorporateHero;